 where lower(trim(i.name)) = lower(trim(o.t));

do $$ begin
  if exists (select 1 from public.items where exc_order is null)
     or (select count(distinct exc_order) from public.items) <> (select count(*) from public.items) then
    raise exception 'curriculum order does not cover every item exactly once';
  end if;
end $$;
alter table public.items alter column exc_order set not null;
-- Deferrable so exercises can be renumbered in one transaction when new ones are inserted.
alter table public.items add constraint items_exc_order_key unique (exc_order) deferrable initially deferred;

-- 2. Items carry their own category, so an item can sit directly under a category.
alter table public.items add column category_id bigint references public.categories(id);
update public.items i set category_id = sc.category_id from public.subcategories sc where sc.id = i.subcategory_id;

-- Decisions 1-2: Alternate Picking Exercise under Right Hand Technique, with no subcategory.
do $$
declare cat_id bigint;
begin
  insert into public.categories (name) values ('Right Hand Technique') returning id into cat_id;
  update public.items set name = 'Alternate Picking Exercise', category_id = cat_id, subcategory_id = null
   where lower(trim(name)) = 'alternative picking';
  if not found then raise exception 'alternative picking item not found'; end if;
  if exists (select 1 from public.items where category_id is null) then
    raise exception 'item without a category';
  end if;
end $$;
alter table public.items alter column category_id set not null;

-- Decisions 3 and 4: subcategory names.
update public.subcategories set name = 'warm up exercise' where name = 'warm up excercise';
update public.subcategories set name = 'Bar Chords' where name = 'barre chords';

-- Decision 7: score is BPM / effective playing rate and must be positive.
alter table public.student_logs add constraint student_logs_score_positive check (score > 0);

